using DayKeep.Core;
using Microsoft.Data.Sqlite;

internal static class RepeatChecks
{
    public static void Run(Action<string,Action> test, string directory)
    {
        var number=0;
        void Case(string name, Action<Fixture> action) => test("L3 " + name,()=>action(new Fixture(Path.Combine(directory,$"l3-{++number}.db"))));
        Case("defaults and customized repeat settings persist",f=> { Assert(f.Task.Reminder.RepeatMinutes==30 && f.Task.Reminder.MaxExtraReminders==3); f.Task=f.Service.Edit(f.Task,new("custom",TaskKind.WaitingForCondition,RepeatMinutes:5,MaxExtraReminders:24)); Assert(f.Service.LoadAll().Single()==f.Task && f.Task.Reminder.MaxExtraReminders==24); });
        Case("rejects invalid interval and cap before storage",f=> { foreach(var draft in new[]{new TaskDraft("bad",TaskKind.Todo,RepeatMinutes:4),new("bad",TaskKind.Todo,RepeatMinutes:1441),new("bad",TaskKind.Todo,MaxExtraReminders:-1),new("bad",TaskKind.Todo,MaxExtraReminders:25)}) Throws<TaskValidationException>(()=>f.Service.Create(draft)); Assert(f.Service.LoadAll().Count==1); });
        Case("three extras follow 09:00 and stop after 10:30",f=> { f.At(9,0); f.Deliver(); foreach(var minute in new[]{30,60,90}) { f.Now=f.Start.AddMinutes(1+minute); Assert(f.Due().Single().Key.Kind==ReminderKind.Repeat); f.Deliver(); } f.At(11,0); Assert(f.Due().Count==0 && f.Progress.ExtraCount==3 && f.Progress.NextRepeatAt is null); });
        Case("ticks and opening without an outcome do not move next time",f=> { f.At(9,0); f.Deliver(); var progress=f.Progress; f.At(9,29); for(var i=0;i<20;i++) Assert(f.Due().Count==0); Assert(f.Progress==progress && progress.NextRepeatAt==f.Start.AddMinutes(31)); });
        Case("fixed and repeat collision merges without using extra budget",f=> { f.EditTimes("09:00, 09:30, 10:00"); f.At(9,0); f.Deliver(); f.At(9,30); Assert(f.Due().Single().Key.Kind==ReminderKind.Fixed); f.Deliver(); Assert(f.Progress.ExtraCount==0); f.At(10,0); f.Deliver(); f.At(10,30); f.Deliver(); Assert(f.Progress.ExtraCount==1); });
        Case("multiple fixed slots share the same daily extra cap",f=> { f.EditTimes("09:00, 14:00"); f.At(9,0); f.Deliver(); foreach(var t in new[]{(9,30),(10,0),(10,30)}) { f.At(t.Item1,t.Item2); f.Deliver(); } f.At(14,0); Assert(f.Due().Single().Key.Kind==ReminderKind.Fixed); f.Deliver(); f.At(14,30); Assert(f.Due().Count==0 && f.Progress.ExtraCount==3); });
        Case("zero cap preserves fixed reminders but disables extras",f=> { f.Task=f.Service.Edit(f.Task,new("no extras",TaskKind.WaitingForCondition,MaxExtraReminders:0)); f.At(9,0); f.Deliver(); f.At(9,30); Assert(f.Due().Count==0 && f.Progress.NextRepeatAt is null); });
        Case("delayed tick stays on original cadence without a burst",f=> { f.At(9,0); f.Deliver(); f.At(9,47); f.Deliver(); Assert(f.Progress.NextRepeatAt==f.Start.AddMinutes(61) && f.Progress.ExtraCount==1 && f.Due().Count==0); });
        Case("snooze overrides intervening fixed and repeat slots",f=> { f.EditTimes("09:00, 09:30"); f.At(9,0); f.Deliver(); f.At(9,10); f.Task=f.Service.Snooze(f.Task,f.Date,60); f.At(9,30); Assert(f.Due().Count==0); f.At(10,10); Assert(f.Due().Single().Key.Kind==ReminderKind.Snooze); f.Deliver(); Assert(f.Progress.SnoozedUntil is null && f.Progress.ExtraCount==0); });
        Case("snooze expiry and fixed minute never produce a second popup",f=> { f.EditTimes("09:00, 09:30"); f.At(9,0); f.Deliver(); f.At(9,0); f.Now=f.Now.AddSeconds(30); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.At(9,30); f.Now=f.Now.AddSeconds(30); f.Deliver(); f.Now=f.Now.AddSeconds(1); Assert(f.Due().Count==0); });
        Case("explicit snooze is honored even with automatic extras disabled",f=> { f.Task=f.Service.Edit(f.Task,new("explicit",TaskKind.WaitingForCondition,MaxExtraReminders:0)); f.At(9,0); f.Task=f.Service.Snooze(f.Task,f.Date,10); f.At(9,10); f.Deliver(); Assert(f.Progress.ExtraCount==0 && f.Progress.NextRepeatAt is null); });
        Case("cross-midnight snooze survives an unselected weekday",f=> { f.Task=f.Service.Edit(f.Task,new("Monday only",TaskKind.WaitingForCondition,Weekdays:1)); f.At(23,50); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.Now=f.Now.AddMinutes(30); Assert(f.Date.DayOfWeek==DayOfWeek.Tuesday && f.Due().Single().Key.Kind==ReminderKind.Snooze); f.Deliver(); f.Now=f.Now.AddMinutes(30); Assert(f.Due().Count==0); });
        Case("today check cancels snooze and every remaining reminder",f=> { f.At(9,0); f.Deliver(); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.Task=f.Service.RecordWaitingCheck(f.Task,f.Date,""); f.At(9,30); Assert(f.Due().Count==0 && f.Progress.SnoozedUntil is null && f.Progress.NextRepeatAt is null); Throws<TaskValidationException>(()=>f.Service.Snooze(f.Task,f.Date,10)); });
        Case("mark-ready anchors a new followup without completing",f=> { f.At(9,0); f.Deliver(); f.At(9,10); f.Task=f.Service.MarkReady(f.Task,f.Date); f.At(9,30); Assert(f.Due().Count==0); f.At(9,40); Assert(f.Due().Single().Task.State==TaskState.Ready && f.Task.CompletedAt is null); });
        Case("pause completion and archive atomically clear scheduled followups",f=> { f.At(9,0); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.Task=f.Service.TogglePause(f.Task); Assert(f.Progress.SnoozedUntil is null); f.Task=f.Service.TogglePause(f.Task); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.Task=f.Service.Complete(f.Task); Assert(f.Progress.SnoozedUntil is null); f.Task=f.Service.UndoComplete(f.Task); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.Task=f.Service.Archive(f.Task); f.At(9,30); Assert(f.Due().Count==0 && f.Progress.SnoozedUntil is null); });
        Case("editing clears pending delay but does not reset daily budget",f=> { f.At(9,0); f.Deliver(); f.At(9,30); f.Deliver(); f.Task=f.Service.Snooze(f.Task,f.Date,30); f.EditTimes("14:00"); Assert(f.Progress.ExtraCount==1 && f.Progress.NextRepeatAt is null && f.Progress.SnoozedUntil is null); });
        Case("next local day resets extra budget and overdue task keeps running",f=> { f.Task=f.Service.Edit(f.Task,new("overdue",TaskKind.WaitingForCondition,DueDate:"2026-10-25",MaxExtraReminders:1)); f.At(9,0); f.Deliver(); f.At(9,30); f.Deliver(); f.Now=f.Start.AddDays(1).AddMinutes(1); f.Deliver(); Assert(f.Progress.ExtraCount==0 && f.Task.State==TaskState.Waiting); f.Now=f.Now.AddMinutes(30); Assert(f.Due().Single().Key.Kind==ReminderKind.Repeat); });
        Case("automatic extras never spill across local midnight",f=> { f.EditTimes("23:50"); f.At(23,50); f.Deliver(); Assert(f.Progress.NextRepeatAt is null); f.Now=f.Now.AddMinutes(30); Assert(f.Due().Count==0); });
        Case("next time accounts for delay and current repeat state",f=> { f.At(9,0); f.Deliver(); Assert(ReminderPlanner.Next(f.Task,new HashSet<Guid>(),f.Now,TimeZoneInfo.Utc,f.Progress)==f.Now.AddMinutes(30)); f.Task=f.Service.Snooze(f.Task,f.Date,60); Assert(ReminderPlanner.Next(f.Task,new HashSet<Guid>(),f.Now,TimeZoneInfo.Utc,f.Progress)==f.Now.AddHours(1)); });
        Case("deadline priority changes only at the local date boundary",f=> { var china=TimeZoneInfo.CreateCustomTimeZone("L3 UTC8",TimeSpan.FromHours(8),"UTC8","UTC8"); var task=f.Task with { DueDate=new(2026,10,26) }; var before=new DateTimeOffset(2026,10,26,15,59,59,TimeSpan.Zero); Assert(ReminderPlanner.DeadlinePriority(task,ReminderPlanner.LocalDate(before,china))==1 && ReminderPlanner.DeadlinePriority(task,ReminderPlanner.LocalDate(before.AddSeconds(1),china))==0); });
        Case("stale snooze cannot overwrite a newer task or progress",f=> { var old=f.Task; f.At(9,0); f.Task=f.Service.Snooze(f.Task,f.Date,30); var progress=f.Progress; Throws<TaskConflictException>(()=>f.Service.Snooze(old,f.Date,60)); Assert(f.Progress==progress && f.Service.LoadAll().Single()==f.Task); });
        Case("stale delivery progress cannot consume the cap twice",f=> { f.At(9,0); var due=f.Due().Single(); f.Deliver(); var progress=f.Progress; Throws<TaskConflictException>(()=>f.Service.RecordDelivery(due,null,f.Now,TimeZoneInfo.Utc)); Assert(f.Progress==progress); });
        Case("progress failure rolls back task revision event and snooze",f=> { Sql(f.Path,"CREATE TRIGGER reject_progress BEFORE INSERT ON reminder_progress BEGIN SELECT RAISE(ABORT,'controlled'); END;"); Throws<SqliteException>(()=>f.Service.Snooze(f.Task,f.Date,30)); Assert(f.Service.LoadAll().Single()==f.Task && f.Service.ReminderSnapshot(f.Date).Progress.Count==0); });
        Case("schema-2 upgrade retains tasks checks and completion snapshots",f=> { f.Task=f.Service.RecordWaitingCheck(f.Task,f.Date,"legacy"); f.Task=f.Service.Complete(f.Task); Sql(f.Path,"DROP TABLE reminder_deliveries; DROP TABLE reminder_days; DROP TABLE reminder_progress; PRAGMA user_version=2;"); f.Service.Initialize(); Assert(f.Service.LoadAll().Single()==f.Task && f.Service.ReminderSnapshot(f.Date).Progress.Count==0 && f.Service.Repository.LoadChecks(f.Task.Id).Count==1); Assert(f.Service.UndoComplete(f.Task).State==TaskState.Waiting); });
        Case("failed schema-1 to 3 migration rolls back outcome column too",f=> { Sql(f.Path,"ALTER TABLE task_checks DROP COLUMN outcome; PRAGMA user_version=1;"); var before=File.ReadAllBytes(f.Path); Throws<SqliteException>(f.Service.Initialize); Assert(before.SequenceEqual(File.ReadAllBytes(f.Path))); });
        Case("saved future and elapsed snooze can be planned by a new service",f=> { f.At(9,0); f.Task=f.Service.Snooze(f.Task,f.Date,30); var restarted=new TaskService(new TaskRepository(f.Path)); restarted.Initialize(); var snapshot=restarted.ReminderSnapshot(f.Date); Assert(ReminderPlanner.Due(snapshot,f.Now.AddMinutes(29),f.Now.AddMinutes(20),TimeZoneInfo.Utc).Count==0); Assert(ReminderPlanner.Due(snapshot,f.Now.AddMinutes(40),f.Now.AddMinutes(40),TimeZoneInfo.Utc).Single().Key.Kind==ReminderKind.Snooze); });
    }
    private static void Assert(bool value) { if(!value) throw new InvalidOperationException("L3 scheduling expectation failed"); }
    private static void Throws<T>(Action action) where T:Exception { try {action();} catch(T) {return;} throw new InvalidOperationException($"Expected {typeof(T).Name}"); }
    private static void Sql(string path,string sql) { using var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Pooling=false}.ToString()); c.Open(); using var command=c.CreateCommand(); command.CommandText=sql; command.ExecuteNonQuery(); }
    private sealed class Fixture
    {
        public string Path { get; }
        public DateTimeOffset Start { get; }=new(2026,10,26,8,59,0,TimeSpan.Zero);
        public DateTimeOffset Now { get; set; }
        public DateOnly Date => DateOnly.FromDateTime(Now.DateTime);
        public TaskService Service { get; }
        public TaskItem Task { get; set; }
        public ReminderProgress Progress => Service.ReminderSnapshot(Date).Progress.Single();
        public Fixture(string path) { Path=path; Now=Start; Service=new(new TaskRepository(path),()=>Now); Service.Initialize(); Task=Service.Create(new("L3 synthetic",TaskKind.WaitingForCondition)); }
        public void At(int hour,int minute) => Now=new(2026,10,26,hour,minute,0,TimeSpan.Zero);
        public IReadOnlyList<ReminderOccurrence> Due() => ReminderPlanner.Due(Service.ReminderSnapshot(Date),Now,Start,TimeZoneInfo.Utc);
        public void Deliver() { var snapshot=Service.ReminderSnapshot(Date); Service.RecordDelivery(Due().Single(),snapshot.Progress.SingleOrDefault(),Now,TimeZoneInfo.Utc); }
        public void EditTimes(string times) => Task=Service.Edit(Task,new(Task.Title,Task.Kind,Times:times));
    }
}
